$esc = [char]27
$semi = [char]59
$fgHex = "$esc[38${semi}2${semi}72${semi}77${semi}70m"
$bgHex = "$esc[48${semi}2${semi}30${semi}33${semi}36m"
$reset = "$esc[0m"

function Decode($b64) {
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
}

