    '.gitignore' = 'IyBBbGxvdyBzcGVjaWZpYyBtYW5kYXRvcnkgZmlsZXMNCiFyZWFkbWUubWQNCiFsaWNlbnNlLm1kDQoNCiMgT1MgZ2VuZXJhdGVkIGZpbGVzDQouRFNfU3RvcmUNClRodW1icy5kYg0KDQojIFByb2plY3QgZ2VuZXJhdGVkL21haW50YWluZWQgZmlsZXMNCi9hcHBzLw0KL1RFTVBMQVRFLw0KL3Byb2plY3QgYXJ0aWZhY3RzLw=='
    'readme.md' = ''
    '.agent/workflows/supabase_management.md' = ''
