    'agent.md' = ''
    'design.md' = ''
    'firebase.md' = ''
    'todo.md' = 'IyBQUk9KRUNUIEJBQ0tMT0cgKFRPRE8pDQoNCiMjIFBSSU9SSVRZOiBBUkNISVRFQ1RVUkUNCiogWyBdIFRhc2sgMQ0KKiBbIF0gVGFzayAyDQoNCiMjIFBPU1QtTVZQDQoqIFsgXSBUYXNrIDENCg=='
