$options = @()
foreach ($k in $apps.Keys) {
    $options += [pscustomobject]@{
        Name = $k
        Type = 'App'
        Selected = $true
    }
}
foreach ($k in $artifacts.Keys) {
    $options += [pscustomobject]@{
        Name = $k
        Type = 'Artifact'
        Selected = $true
    }
}
foreach ($k in $skills.Keys) {
    $options += [pscustomobject]@{
        Name = $k
        Type = 'Skill'
        Selected = $true
    }
}

$index = 0
$running = $true

Write-Host "$bgHex" -NoNewline
Clear-Host

while ($running) {
    [Console]::SetCursorPosition(0,0)
    Write-Host "$bgHex$fgHex  ___  ___   _   ___ ___ ___  _    ___  "
    Write-Host "$bgHex$fgHex / __|/ __| /_\ | __| __/ _ \| |  |   \ "
    Write-Host "$bgHex$fgHex \__ \ (__ / _ \| _|| _| (_) | |__| |) |"
    Write-Host "$bgHex$fgHex |___/\___/_/ \_\_| |_| \___/|____|___/ "
    Write-Host "$reset$bgHex"
    Write-Host "$bgHex"
    Write-Host "$bgHex  Use Up/Down to navigate, Space to toggle, 'A' for all/none, Enter to execute."
    Write-Host "$bgHex"
    
    $i = 0
    Write-Host "$bgHex  Apps:" -ForegroundColor Cyan
    foreach ($opt in $options) {
        if ($opt.Type -eq 'Artifact' -and ($i -gt 0) -and $options[$i-1].Type -eq 'App') {
            Write-Host "$bgHex"
            Write-Host "$bgHex  Artifacts:" -ForegroundColor Cyan
        }
        if ($opt.Type -eq 'Skill' -and ($i -gt 0) -and $options[$i-1].Type -eq 'Artifact') {
            Write-Host "$bgHex"
            Write-Host "$bgHex  Skills:" -ForegroundColor Cyan
        }
        $prefix = '  '
        if ($i -eq $index) { $prefix = '> ' }
        $checkbox = '[ ]'
        if ($opt.Selected) { $checkbox = '[X]' }
        Write-Host "$bgHex$prefix$checkbox $($opt.Name)                   "
        $i++
    }
    
    $key = $Host.UI.RawUI.ReadKey('NoEcho,IncludeKeyDown')
    if ($key.VirtualKeyCode -eq 38) {
        $index--
        if ($index -lt 0) { $index = $options.Count - 1 }
    } elseif ($key.VirtualKeyCode -eq 40) {
        $index++
        if ($index -ge $options.Count) { $index = 0 }
    } elseif ($key.VirtualKeyCode -eq 32) {
        $options[$index].Selected = -not $options[$index].Selected
    } elseif ($key.VirtualKeyCode -eq 65) {
        $all = $true
        foreach ($o in $options) { if (-not $o.Selected) { $all = $false } }
        $newState = -not $all
        foreach ($o in $options) { $o.Selected = $newState }
        Clear-Host
    } elseif ($key.VirtualKeyCode -eq 13) {
        $running = $false
    }
}

Clear-Host
Write-Host "$reset" -NoNewline

foreach ($k in $core.Keys) {
    $path = Join-Path $PSScriptRoot $k
    if (-not (Test-Path $path)) {
        $parent = Split-Path $path
        if ($parent -and -not (Test-Path $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
        Set-Content -Path $path -Value (Decode $core[$k])
    }
}

foreach ($opt in $options) {
    if ($opt.Selected) {
        $tg = $null
        if ($opt.Type -eq 'App') { $tg = $apps[$opt.Name] }
        elseif ($opt.Type -eq 'Artifact') { $tg = @{ "project artifacts/$($opt.Name)" = $artifacts[$opt.Name] } }
        elseif ($opt.Type -eq 'Skill') { $tg = $skills[$opt.Name] }
        
        foreach ($f in $tg.Keys) {
            $dest = Join-Path $PSScriptRoot $f
            if (-not (Test-Path $dest)) {
                $p = Split-Path $dest
                if ($p -and -not (Test-Path $p)) { New-Item -ItemType Directory -Force -Path $p | Out-Null }
                Set-Content -Path $dest -Value (Decode $tg[$f])
                Write-Host "Created: $f" -ForegroundColor Green
            } else {
                Write-Host "Skipped: $f" -ForegroundColor Yellow
            }
        }
    }
}

if ($PSCommandPath) { Remove-Item -Path $PSCommandPath -Force }
